class ResourceOwner
{
    int* data_;
    size_t size_;
public:
    ResourceOwner(size_t n) : data_(new int[n]), size_(n) {}
    ~ResourceOwner() { delete[] data_; }
    ResourceOwner(const ResourceOwner& other)  // copy ctor
        : data_(new int[other.size_]), size_(other.size_)
        {
        std::copy(other.data_, other.data_ + size_, data_);
    }
    ResourceOwner& operator=(const ResourceOwner& other) // copy assign
    {
        if (this != &other)
        {
            delete[] data_;
            data_ = new int[other.size_];
            size_ = other.size_;
            std::copy(other.data_, other.data_ + size_, data_);
        }
        return *this;
    }
    ResourceOwner(ResourceOwner&& other) noexcept  // move ctor
        : data_(other.data_), size_(other.size_)
        {
        other.data_ = nullptr; other.size_ = 0;
    }
    ResourceOwner& operator=(ResourceOwner&& other) noexcept // move assign
    {
        if (this != &other) { delete[] data_; data_ = other.data_; size_ = other.size_;
            other.data_ = nullptr; other.size_ = 0; }
        return *this;
    }
};

