class Buffer
{
    int* data_;
    size_t size_;
public:
    Buffer(size_t n) : data_(new int[n]), size_(n) {}
    ~Buffer() { delete[] data_; }

    // Move constructor
    Buffer(Buffer&& other) noexcept
        : data_(other.data_), size_(other.size_)
        {
        other.data_ = nullptr;  // leave other in valid state
        other.size_ = 0;
    }

    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept
    {
        if (this != &other)
        {
            delete[] data_;  // release current
            data_ = other.data_;  size_ = other.size_;
            other.data_ = nullptr;  other.size_ = 0;
        }
        return *this;
    }
};

