std::string minWindow(std::string s, std::string t) {
    if (s.empty() || t.empty()) return "";
    std::vector<int> target(128, 0);
    for (char c : t) target[c]++;

    int required = 0;
    for (int count : target) if (count > 0) required++;

    std::vector<int> window(128, 0);
    int formed = 0, left = 0, minLen = INT_MAX, startIdx = 0;

    for (int right = 0; right < s.size(); ++right) {
        char c = s[right];
        window[c]++;
        if (target[c] > 0 && window[c] == target[c]) formed++;

        while (left <= right && formed == required) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                startIdx = left;
            }
            char leftChar = s[left++];
            window[leftChar]--;
            if (target[leftChar] > 0 && window[leftChar] < target[leftChar]) {
                formed--;
            }
        }
    }
    return minLen == INT_MAX ? "" : s.substr(startIdx, minLen);
}

