class ConsistentHashRing {
private:
    std::map<uint32_t, std::string> ring; // Sorted hash ring
    int virtualNodes;
    std::hash<std::string> hasher;

public:
    explicit ConsistentHashRing(int vnodes = 100) : virtualNodes(vnodes) {}

    void addServer(const std::string& server) {
        for (int i = 0; i < virtualNodes; ++i) {
            std::string vNodeKey = server + "#" + std::to_string(i);
            uint32_t hashVal = static_cast<uint32_t>(hasher(vNodeKey));
            ring[hashVal] = server;
        }
    }

    std::string getServer(const std::string& key) const {
        if (ring.empty()) return "";
        uint32_t hashVal = static_cast<uint32_t>(hasher(key));
        auto it = ring.lower_bound(hashVal);
        if (it == ring.end()) {
            it = ring.begin(); // Wrap around ring
        }
        return it->second;
    }
};

