class Base62Codec {
private:
    inline static const std::string BASE62_CHARS = 
        "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

public:
    static std::string encode(uint64_t id) {
        if (id == 0) return "0";
        std::string shortCode;
        while (id > 0) {
            shortCode.push_back(BASE62_CHARS[id % 62]);
            id /= 62;
        }
        std::reverse(shortCode.begin(), shortCode.end());
        return shortCode;
    }

    static uint64_t decode(const std::string& code) {
        uint64_t id = 0;
        for (char c : code) {
            size_t pos = BASE62_CHARS.find(c);
            if (pos == std::string::npos) return 0;
            id = id * 62 + pos;
        }
        return id;
    }
};

#include <vector>
#include <atomic>
#include <optional>

template <typename T, size_t Capacity>
class LockFreeQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be power of 2");
private:
    std::vector<T> buffer;
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    LockFreeQueue() : buffer(Capacity) {}

    bool push(const T& item) {
        size_t currentTail = tail.load(std::memory_order_relaxed);
        if (currentTail - head.load(std::memory_order_acquire) >= Capacity) {
            return false; // Queue full
        }
        buffer[currentTail & (Capacity - 1)] = item;
        tail.store(currentTail + 1, std::memory_order_release);
        return true;
    }

    std::optional<T> pop() {
        size_t currentHead = head.load(std::memory_order_relaxed);
        if (currentHead == tail.load(std::memory_order_acquire)) {
            return std::nullopt; // Queue empty
        }
        T item = buffer[currentHead & (Capacity - 1)];
        head.store(currentHead + 1, std::memory_order_release);
        return item;
    }
};
